import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"12、【否】 坤下乾上","description":"横渠易说 - 12、【否】 坤下乾上","frontmatter":{"title":"12、【否】 坤下乾上","description":"横渠易说 - 12、【否】 坤下乾上"},"headers":[],"relativePath":"zh/classics/hengqu/014.md","filePath":"zh/classics/hengqu/014.md"}'),l={name:"zh/classics/hengqu/014.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_12、【否】-坤下乾上" tabindex="-1">12、【否】 坤下乾上 <a class="header-anchor" href="#_12、【否】-坤下乾上" aria-label="Permalink to “12、【否】 坤下乾上”">​</a></h1><h3 id="彖曰-否之匪人-不利君子贞-大往小来-则是天地不交而万物不通也-上下不交而天下无邦也。内阴而外阳-内柔而外刚-内小人而外君子-小人道长-君子道消也。" tabindex="-1">彖曰：“否之匪人，不利君子贞，大往小来”，则是天地不交而万物不通也，上下不交而天下无邦也。内阴而外阳，内柔而外刚，内小人而外君子，小人道长，君子道消也。 <a class="header-anchor" href="#彖曰-否之匪人-不利君子贞-大往小来-则是天地不交而万物不通也-上下不交而天下无邦也。内阴而外阳-内柔而外刚-内小人而外君子-小人道长-君子道消也。" aria-label="Permalink to “彖曰：“否之匪人，不利君子贞，大往小来”，则是天地不交而万物不通也，上下不交而天下无邦也。内阴而外阳，内柔而外刚，内小人而外君子，小人道长，君子道消也。”">​</a></h3><h3 id="象曰-天地不交-否-君子以险德辟难-不可荣以禄。" tabindex="-1">象曰：天地不交，否，君子以险德辟难，不可荣以禄。 <a class="header-anchor" href="#象曰-天地不交-否-君子以险德辟难-不可荣以禄。" aria-label="Permalink to “象曰：天地不交，否，君子以险德辟难，不可荣以禄。”">​</a></h3><p>盖言上下不交便天下无邦，有邦而与无邦同，以不成国体也。在天下，他国皆无道，只一邦治，亦不可言天下无道，须是都不治然后是天下无道也。于否之时，则天下无邦也。古之人，一邦不治，别之一邦，直至天下皆无邦可之，则止有隐耳。无道而隐，则惟是有朋友之乐而已。子欲居九夷，未敢必天下之无邦，或夷狄有道，于今海上之国尽有仁厚之治者。</p><h3 id="初六-拔茅茹-以其汇-贞吉亨。-象曰-拔茅贞吉-志在君也。" tabindex="-1">初六，拔茅茹，以其汇，贞吉亨。 象曰：“拔茅贞吉”，志在君也。 <a class="header-anchor" href="#初六-拔茅茹-以其汇-贞吉亨。-象曰-拔茅贞吉-志在君也。" aria-label="Permalink to “初六，拔茅茹，以其汇，贞吉亨。 象曰：“拔茅贞吉”，志在君也。”">​</a></h3><p>柔顺处下，居否以静者也。能以类正，吉而必亨，不事苟合，志在得主者欤!</p><h3 id="六二-包承-小人吉-大人否-亨。-象曰-大人否亨了-不乱群也。" tabindex="-1">六二，包承，小人吉，大人否，亨。 象曰：“大人否亨了”，不乱群也。 <a class="header-anchor" href="#六二-包承-小人吉-大人否-亨。-象曰-大人否亨了-不乱群也。" aria-label="Permalink to “六二，包承，小人吉，大人否，亨。 象曰：“大人否亨了”，不乱群也。”">​</a></h3><p>处二阴之间，上顺下容，众不可异，故其道否乃亨。</p><h3 id="六三-包羞。-象曰-包羞-位不当也。" tabindex="-1">六三，包羞。 象曰：“包羞”，位不当也。 <a class="header-anchor" href="#六三-包羞。-象曰-包羞-位不当也。" aria-label="Permalink to “六三，包羞。 象曰：“包羞”，位不当也。”">​</a></h3><p>处否而进，履非其位，非知耻者也。</p><h3 id="九四-有命无咎-畴离祉。-象曰-有命无咎-志行也。" tabindex="-1">九四，有命无咎，畴离祉。 象曰：“有命无咎”，志行也。 <a class="header-anchor" href="#九四-有命无咎-畴离祉。-象曰-有命无咎-志行也。" aria-label="Permalink to “九四，有命无咎，畴离祉。 象曰：“有命无咎”，志行也。”">​</a></h3><p>居否之世，以阳处阴，有应于下，故虽有所命无咎也。</p><h3 id="九五-休否-大人吉。其亡其亡-系于苞桑。-象曰-大人之吉-位正当也。" tabindex="-1">九五，休否，大人吉。其亡其亡，系于苞桑。 象曰：大人之吉，位正当也。 <a class="header-anchor" href="#九五-休否-大人吉。其亡其亡-系于苞桑。-象曰-大人之吉-位正当也。" aria-label="Permalink to “九五，休否，大人吉。其亡其亡，系于苞桑。 象曰：大人之吉，位正当也。”">​</a></h3><p>以亡为惧，故能休其否。包桑，从下丛生之桑，丛生则其根牢。书云“厥草惟包”，如竹丛芦苇之类。河朔之桑，多从根斩条取叶，其生丛然。</p><h3 id="上九-倾否-先否后喜。-象曰-否终则倾-何可长也" tabindex="-1">上九，倾否，先否后喜。 象曰：否终则倾，何可长也! <a class="header-anchor" href="#上九-倾否-先否后喜。-象曰-否终则倾-何可长也" aria-label="Permalink to “上九，倾否，先否后喜。 象曰：否终则倾，何可长也!”">​</a></h3>',15)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
